import assert from 'node:assert/strict';
import { createBoard, addCard, moveCard, filterCards } from './store.mjs';
let b = createBoard();
b = addCard(b, 'todo', 'Build auth');
b = addCard(b, 'todo', 'Write tests');
const id = b.columns.todo[0].id;
b = moveCard(b, id, 'doing', 0);
assert.equal(b.columns.todo.length, 1);
assert.equal(b.columns.doing.length, 1);
assert.equal(filterCards(b, 'auth').length, 1);
